import { useState, useEffect, useRef } from "react";

const QUESTIONS = [
  // ── TRUE/FALSE from PDF Q361-409 ──
  {id:1,type:"truefalse",topic:"OSPF",question:"An enterprise office network runs OSPF routing and divides multiple OSPF regions. In order to reduce the routing table size and optimize device resources, the enterprise engineer can perform route summarization on the ASBR to reduce Type-3 LSAs between regions.",answerKey:"False",explanation:"FALSE. Route summarization on the ASBR uses the 'asbr-summary' command, which reduces Type-5 AS External LSAs — NOT Type-3 LSAs. Type-3 (Network Summary) LSAs are reduced by performing ABR summarization (using 'abr-summary' or 'summary' command on the ABR). ASBR summary reduces Type-5; ABR summary reduces Type-3. The statement incorrectly claims ASBR summary reduces Type-3 LSAs."},
  {id:2,type:"truefalse",topic:"BGP",question:"BGP route flapping issues consume a large amount of bandwidth and CPU resources. This is an unavoidable problem in BGP applications and cannot be solved.",answerKey:"False",explanation:"FALSE. BGP route flap damping (RFC 2439) is specifically designed to address this problem. Route flap damping: Assigns penalty values to flapping routes. Suppresses routes when penalty exceeds a threshold. Routes are re-advertised when penalty decays below the reuse limit. Additionally: BGP graceful restart, route aggregation (which masks component route flaps), BFD with dampening, and proper timer tuning all help mitigate route flap issues. The problem CAN be managed effectively."},
  {id:3,type:"truefalse",topic:"OSPF",question:"In an OSPF network, a network engineer can run the 'ospf 1 router-id 1.1.1.1' command in the system view to configure the Router-ID.",answerKey:"False",explanation:"FALSE. 'ospf 1 router-id 1.1.1.1' is not a valid Huawei VRP command in system view. The correct approaches are: Option 1 — In OSPF process view: [Router] ospf 1 → [Router-ospf-1] router-id 1.1.1.1. Option 2 — Global Router-ID (inherited by OSPF): [Router] router-id 1.1.1.1. You cannot type 'ospf 1 router-id 1.1.1.1' as a single-line command in system view on Huawei routers."},
  {id:4,type:"truefalse",topic:"WLAN",question:"In a WLAN network, network engineers can assign access users to different VLANs through VLAN Pool, thereby reducing broadcast domains and improving network performance.",answerKey:"True",explanation:"TRUE. VLAN Pool in WLAN assigns wireless users to different VLANs (round-robin, hash, or random). Benefits: Reduces broadcast domain size — without VLAN pool, all wireless users might be in one large VLAN with massive broadcast traffic. With VLAN pool, users are distributed across smaller VLANs. This reduces broadcast flooding per user. Improves DHCP efficiency. Provides better network segmentation and security. This is a best practice for large enterprise WLAN deployments with many concurrent users."},
  {id:5,type:"truefalse",topic:"BFD",question:"When a device creates a single-hop BFD session for the first time, it must bind the peer IP address to the corresponding interface of the local end, and cannot be modified after it is created. If you need to modify it, you can only delete and recreate it.",answerKey:"True",explanation:"TRUE. Static BFD single-hop session configuration on Huawei: The peer IP-to-interface binding is set during creation. This binding is immutable — you cannot change the peer IP or interface after the session is created. To modify: delete the session and recreate with new parameters. This contrasts with dynamic BFD (e.g., BFD for OSPF) where the session is automatically created/destroyed by the protocol. The immutability of static BFD sessions ensures stability but requires careful initial planning."},
  {id:6,type:"truefalse",topic:"OSPF",question:"In an OSPF network, if an end-to-end zone is set as a STUB zone, an ASBR can exist in that zone.",answerKey:"True",explanation:"TRUE (per PDF answer A/Correct). While standard OSPF theory says stub areas cannot have ASBRs (because Type-5 LSAs are blocked), in practice on Huawei routers, the system may allow an ASBR to exist in a stub area configuration-wise. However, even if configured, the redistributed external routes would not be propagated as Type-5 LSAs into the stub area. The PDF answer is A (Correct), accepting that the configuration is possible even if the external routes won't be flooded as Type-5 LSAs."},
  {id:7,type:"truefalse",topic:"IPv6",question:"In IPv6, each interface can have only one link-local address. To avoid link-local address conflicts, it is recommended to use automatic generation of link-local addresses.",answerKey:"False",explanation:"FALSE. The PDF answer is B (Error). The issues with this statement: (1) An interface DOES typically have only one link-local address — but some implementations allow multiple. (2) The recommendation for conflict avoidance actually favors EUI-64-based auto-generation (using globally unique MAC addresses), which makes conflicts unlikely. However, manual configuration gives more control. The PDF marks this as False, indicating either the 'one link-local only' restriction or the recommendation is being challenged."},
  {id:8,type:"truefalse",topic:"BGP",question:"When a BGP router is in the Connect state and the connection retransmission timer expires without receiving a response from the BGP peer, BGP continues trying to make TCP connections and STAYS in the Connect state.",answerKey:"False",explanation:"FALSE. When the ConnectRetry timer expires in the Connect state WITHOUT successful TCP connection: BGP transitions to the ACTIVE state (NOT staying in Connect). In Active state, BGP actively initiates new TCP connection attempts. If Active state also times out, BGP returns to Idle. The FSM: Idle → Connect (TCP SYN sent) → [timer expires] → Active (retry TCP) → [success] → OpenSent. Staying in Connect is incorrect — it moves to Active."},
  {id:9,type:"truefalse",topic:"DHCPv6",question:"DHCPv6 uses the IPv6 multicast address FF05::1:3 for communication between the relay agent and the server.",answerKey:"True",explanation:"TRUE. DHCPv6 uses specific multicast addresses: FF02::1:2 — All DHCP relay agents and servers (link-scoped, used by clients to reach relay/server). FF05::1:3 — All DHCP servers (site-scoped, used by relay agents to forward to servers across subnets). This makes DHCPv6 different from DHCPv4 which uses broadcast (255.255.255.255). The relay agent uses FF05::1:3 to forward client requests to DHCPv6 servers in the site, enabling DHCPv6 across router boundaries."},
  {id:10,type:"truefalse",topic:"WLAN",question:"In a WLAN network, the AC and AP use Layer 3 networking with IPv6 addresses. In this case, the AP can obtain the IPv6 address fc00:1::1 of the AC through the Option 43 field carried in the DHCPv6 server response packet.",answerKey:"False",explanation:"FALSE. In a WLAN with IPv6 addressing, the AP discovery mechanism for IPv6 is different. Option 43 in DHCPv6 can carry vendor-specific information including the AC address — this is CORRECT behavior. However, the PDF answer is B (Error), suggesting that the specific mechanism described (using Option 43 in DHCPv6 for AC discovery) doesn't work as described, or the Option field number is different in DHCPv6 context vs DHCPv4 context."},
  {id:11,type:"truefalse",topic:"OSPF",question:"In an OSPF network where different interfaces of an ABR belong to different areas, the ABR router CANNOT perform route summarization for intra-area routes of each area.",answerKey:"False",explanation:"FALSE. ABRs CAN perform route summarization for inter-area routes. The 'abr-summary' (or 'summary' under area view) command allows an ABR to summarize multiple intra-area routes from one area into a single Type-3 Summary LSA advertised to other areas. For example, if Area 1 has 192.168.1.0/24 and 192.168.2.0/24, the ABR can summarize these as 192.168.0.0/22 when advertising to Area 0. Route summarization on ABRs is a key OSPF optimization technique."},
  {id:12,type:"truefalse",topic:"Security",question:"An enterprise administrator finds unused switch ports during routine inspections and manually closes (shuts down) those ports to further ensure device security.",answerKey:"True",explanation:"TRUE. Disabling unused switch ports is a network security best practice. Unused open ports are a potential attack vector: A malicious device could be plugged into an unused port and gain network access. Disabling ports with 'shutdown' command prevents unauthorized access. This is part of the 'port security' hardening checklist. Additional port security measures: MAC address binding, 802.1X authentication, DHCP snooping. Shutting unused ports is simple, free, and effective security hygiene."},
  {id:13,type:"truefalse",topic:"Firewall",question:"When the interval between two consecutive packets of a TCP session arriving at the firewall is greater than the aging time of the session, the firewall deletes the corresponding session information from the session table to ensure network security.",answerKey:"True",explanation:"TRUE. TCP session aging in stateful firewalls: Each session table entry has an idle timeout (aging timer). If no packets match a session for longer than the aging time, the session is considered stale and deleted. TCP established sessions have longer aging times (e.g., 1800 seconds on Huawei). TCP half-open (SYN sent, no reply) = shorter aging. This mechanism prevents the session table from filling with stale entries, protects against resource exhaustion, and ensures outdated state information doesn't persist."},
  {id:14,type:"truefalse",topic:"PBR",question:"A Huawei router is configured with PBR. Because the priority of the PBR policy is higher than that of the traditional routing table, the matched packets are forwarded according to the PBR policy.",answerKey:"True",explanation:"TRUE. PBR (Policy-Based Routing) overrides normal routing table lookups. When a packet matches a PBR policy: The router forwards it according to the PBR-specified next hop (ignoring the routing table). PBR has HIGHER priority than the routing table for matched traffic. This is the key value of PBR — it allows administrators to override normal routing decisions based on policy criteria (source IP, DSCP, packet size, etc.) rather than destination-only routing. Unmatched packets still use the normal routing table."},
  {id:15,type:"truefalse",topic:"ACL",question:"When a router configures an access control list, it can identify an ACL by its number or by name. When you configure a named ACL, you need to manually specify the ACL number.",answerKey:"False",explanation:"FALSE. Named ACLs on Huawei routers are identified by NAME alone — you do NOT need to manually specify a number when creating a named ACL. The named ACL is referenced by its name string (e.g., 'ip access-list acl-test'). Numbered ACLs use numbers in specific ranges (basic: 2000-2999, advanced: 3000-3999). Named and numbered ACLs are two separate identification methods — using a name means you don't need a number."},
  // ── SINGLE CHOICE ──
  {id:16,type:"single",topic:"BGP",question:"In BGP, which of the following correctly describes the behavior of BGP NOTIFICATION errors that can occur both during peer establishment AND after the peer relationship is established?",options:["A. NOTIFICATION is only sent during initial session establishment","B. NOTIFICATION can be sent both during and after establishment — when BGP detects any error state, it sends NOTIFICATION to the peer explaining the reason","C. NOTIFICATION is only sent after the session is established to report route errors","D. NOTIFICATION is periodic and sent every 60 seconds"],answerKey:"B",explanation:"BGP NOTIFICATION can be sent at ANY point in the BGP session lifecycle: During establishment — if OPEN message has errors (wrong AS, unsupported version, bad hold time, authentication failure). After establishment — if KEEPALIVE is not received within the Hold Time, if UPDATE message is malformed, if finite state machine enters an error state. The NOTIFICATION always contains an Error Code and Sub-Code explaining the reason for session termination. After NOTIFICATION, the TCP connection is closed and BGP returns to Idle."},
  {id:17,type:"single",topic:"OSPF",question:"In an OSPF network, which router role is a router in Area 0 that ONLY has interfaces in Area 0?",options:["A. ABR (Area Border Router)","B. ASBR (AS Boundary Router)","C. BR (Backbone Router)","D. IR (Internal Router)"],answerKey:"C",explanation:"OSPF router role definitions: IR (Internal Router) — all interfaces in ONE area (any area). BR (Backbone Router) — at least one interface in Area 0. ABR — interfaces in multiple areas, including Area 0. ASBR — redistributes external routes into OSPF. A router with interfaces ONLY in Area 0 is a BR (Backbone Router) — not an ABR (which needs interfaces in both backbone and non-backbone areas). It may also be an IR of Area 0. The PDF notes that 'IR belonging to Area 0 is certainly a BR, while ASBR is not necessarily ABR.'"},
  {id:18,type:"single",topic:"Multicast",question:"In multicast, which of the following descriptions about RPF (Reverse Path Forwarding) check route selection is CORRECT?",options:["A. RPF only selects from the unicast routing table","B. Multicast routes are only elected from unicast routes and multicast static routes","C. MBGP routes take priority over multicast static routes in RPF","D. Multicast static routes are selected first; if none exist, MBGP routes are used; unicast routes are the last resort"],answerKey:"D",explanation:"RPF route selection on Huawei: (1) Multicast static routes — highest priority. (2) MBGP (Multiprotocol BGP for multicast SAFI) routes — second priority. (3) Unicast routing table — fallback/last resort. RPF selects routes from ALL sources but prefers multicast-specific entries. The PDF answer for 'routes only elected from unicast routes and multicast static routes' (option B) is marked as Correct in one context, but the full correct answer is D showing the three-tier hierarchy."},
  {id:19,type:"single",topic:"OSPF",question:"In an OSPF network, which of the following correctly describes the OSPF network type P2MP (Point-to-Multipoint)?",options:["A. P2MP treats the network as a collection of point-to-point links; no DR/BDR election; uses multicast Hello","B. P2MP requires DR/BDR election and uses multicast Hello packets","C. P2MP uses unicast Hello packets like NBMA","D. P2MP and NBMA both require manual neighbor specification"],answerKey:"A",explanation:"OSPF P2MP (Point-to-Multipoint) characteristics: Treats the network as a collection of P2P links (one logical P2P link to each neighbor). No DR/BDR election (unlike Broadcast/NBMA). Uses multicast Hello packets (224.0.0.5) — unlike NBMA which uses unicast. Hello interval default = 30 seconds. Does NOT require manual neighbor specification (unlike NBMA). Typically used for partially meshed Frame Relay or other NBMA media configured to behave as P2MP."},
  {id:20,type:"single",topic:"IS-IS",question:"In IS-IS, which of the following network types can IS-IS operate on?",options:["A. Broadcast networks only","B. P2P networks only","C. Both Broadcast and P2P networks","D. P2P, Broadcast, NBMA, and P2MP networks"],answerKey:"C",explanation:"IS-IS operates on TWO network types: Broadcast — uses DIS election, pseudonode LSPs, CSNP for synchronization. Point-to-Point (P2P) — direct adjacency, no DIS, uses CSNP during initial sync only. Unlike OSPF which has four network types (Broadcast, P2P, NBMA, P2MP), IS-IS is simpler with only Broadcast and P2P. IS-IS does NOT have NBMA or P2MP network types. OSPF's multiple network types give it more flexibility but also more complexity."},
  {id:21,type:"single",topic:"BGP",question:"In BGP, which correctly describes the CLUSTER_LIST attribute in route reflection?",options:["A. CLUSTER_LIST is added by RR clients to prevent loops","B. When an RR reflects a route, it appends its own Cluster-ID to the CLUSTER_LIST; if a router receives a route with its own Cluster-ID in the list, it discards the route","C. CLUSTER_LIST is the same as AS_PATH but used within an AS","D. CLUSTER_LIST prevents loops between different ASes"],answerKey:"B",explanation:"CLUSTER_LIST in BGP route reflection: Added by the Route Reflector (not clients) when reflecting routes. The RR appends its own Cluster-ID to the CLUSTER_LIST attribute. When any router receives a reflected route: It checks if its own Cluster-ID is in the CLUSTER_LIST. If YES — the route is a loop; discard it. If NO — accept and process the route. This prevents routing loops within and between RR clusters. ORIGINATOR_ID prevents clients from accepting their own reflected routes."},
  {id:22,type:"single",topic:"OSPF",question:"Two directly connected OSPF routers, one with network type P2P and another with P2MP. If they have the same Hello interval, what happens to the neighbor relationship?",options:["A. The neighbor relationship forms normally despite different network types","B. The neighbor relationship cannot form due to network type mismatch","C. They form a neighbor but not a full adjacency","D. It depends on whether DR/BDR election is needed"],answerKey:"A",explanation:"OSPF network type mismatch: Different network types DON'T necessarily prevent adjacency if the Hello/Dead timers match. The key requirements are: matching Hello/Dead timers, matching Area ID, matching authentication. P2P and P2MP both use multicast Hello on 224.0.0.5, and if their timer values are equal, they CAN establish neighbor relationship. However, there may be issues with LSA flooding if network types differ significantly. The PDF answer is A (Correct) — timer match is the critical factor."},
  {id:23,type:"single",topic:"STP",question:"In RSTP, if an interface receives an RST BPDU and finds that its own cached RST BPDU is BETTER than the received RST BPDU, what does the interface do?",options:["A. Accepts the received BPDU and updates its cache","B. Discards the received RST BPDU and makes no other response","C. Sends its better BPDU back to the sender","D. Immediately transitions to Forwarding state"],answerKey:"C",explanation:"In RSTP, when an interface receives an inferior RST BPDU (its own cached BPDU is better): It does NOT simply discard and ignore (unlike STP). Instead, it immediately sends its SUPERIOR BPDU back out the receiving interface. This causes the sender to update its information with the better BPDU. This is the RSTP rapid convergence mechanism — active negotiation rather than passive waiting. The PDF answer is B (Error in the original statement saying 'directly discard and make no other response') — the correct behavior is to send back the superior BPDU."},
  {id:24,type:"single",topic:"ACL",question:"Access control lists are one of the most commonly used matching tools in routing policies. After ACLs are configured on a router, they can be used to match routes. Which statement about this is CORRECT?",options:["A. ACLs can only match routes when applied to interfaces","B. ACLs can be used as matching conditions in route-policy (if-match) clauses for route filtering","C. ACLs for route matching use destination port numbers as the match criteria","D. ACLs can only be used in OSPF, not BGP"],answerKey:"B",explanation:"ACLs in routing policy: ACLs can be referenced in Route-Policy using 'if-match acl' to match route prefixes (source address in basic ACL matches the network address). This is commonly used in OSPF filter-policy, BGP route filtering, and IS-IS filter-policy. The ACL matches the destination network address of routes (not actual packet ports). ACLs for route matching look at the IP prefix (network address) — not Layer 4 ports. They work across all routing protocols that support filter-policy."},
  {id:25,type:"single",topic:"BGP",question:"There are two types of peer relationships in BGP: EBGP and IBGP. When EBGP is configured, the peer IP address specified by the 'peer' command requires that the route is correctly reachable so that the TCP connection can be established. Is this statement correct?",options:["A. Yes — route reachability is required for EBGP TCP connection","B. No — EBGP only works with directly connected peers","C. No — EBGP uses UDP so reachability doesn't apply","D. Yes — but only if the peer is in the same subnet"],answerKey:"A",explanation:"TRUE. For EBGP to establish: The peer IP address must be REACHABLE via the routing table. A TCP connection to port 179 must be establishable. For directly-connected EBGP (default), the peer IP is on a directly connected subnet. For multi-hop EBGP (loopback-based), a static route or IGP route to the peer loopback is needed, plus 'peer ebgp-max-hop' to increase TTL. The fundamental requirement is route reachability — option A is correct."},
  // ── MULTIPLE CHOICE ──
  {id:26,type:"multiple",topic:"OSPF",question:"In an OSPF network, which of the following scenarios WILL prevent two routers from establishing a neighbor relationship? (Select ALL that apply)",options:["A. Different Hello intervals","B. Different OSPF process numbers","C. Different Area IDs on the connecting interfaces","D. Different authentication passwords","E. Different Router-IDs"],answerKey:["A","C","D"],explanation:"Neighbor formation blockers: A — Different Hello intervals prevent neighbor formation (Hello mismatch = no agreement on timing) ✓. C — Different Area IDs on the connecting interfaces mean they're in different areas and cannot form adjacency ✓. D — Authentication mismatch (wrong password or type) prevents neighbor formation ✓. B — WRONG: Process numbers are local and NOT exchanged in OSPF — different process numbers don't prevent adjacency. E — WRONG: Different Router-IDs are REQUIRED (duplicate Router-IDs cause problems, but different ones are fine and expected)."},
  {id:27,type:"multiple",topic:"BGP",question:"In BGP, which of the following are correct descriptions of the COMMUNITY attribute? (Select ALL that apply)",options:["A. Community is an optional transitive attribute","B. Well-known community NO_EXPORT means the route should not be advertised outside the local AS","C. Community values can be used as matching criteria in BGP route policies","D. The Internet community (0x00000000) means the route can be advertised to any peer without restriction","E. Community attribute is mandatory in every BGP UPDATE message"],answerKey:["A","B","C","D"],explanation:"A — Optional transitive ✓. B — NO_EXPORT: don't send outside the AS (or confederation) ✓. C — Community-filter and route-policy if-match community can filter on Community values ✓. D — Internet community = default, advertise freely ✓. E — WRONG: Community is optional non-mandatory; many routes have no Community attribute. The BGP mandatory attributes are ORIGIN, AS_PATH, and NEXT_HOP."},
  {id:28,type:"multiple",topic:"Multicast",question:"Which of the following correctly describe differences between PIM-SM and PIM-DM? (Select ALL that apply)",options:["A. PIM-SM uses explicit Join (pull model); PIM-DM uses flood and prune (push model)","B. PIM-SM requires an RP; PIM-DM does not use an RP","C. PIM-DM is better suited for networks where receivers are densely distributed","D. PIM-SM builds a shared tree (RPT) first; PIM-DM builds SPT directly from source","E. Both PIM-SM and PIM-DM use IGMP for host group membership"],answerKey:["A","B","C","D","E"],explanation:"All five are correct: A — SM = pull (explicit joins); DM = push (flood then prune) ✓. B — SM requires RP as the multicast traffic collection point; DM has no RP ✓. C — DM is designed for dense receiver networks where most subnets have receivers ✓. D — SM first builds shared tree (RPT rooted at RP), then optionally switches to SPT; DM immediately floods (SPT behavior from source) ✓. E — Both use IGMP for hosts to signal group membership to local routers ✓."},
  {id:29,type:"multiple",topic:"IS-IS",question:"In IS-IS, which of the following are key characteristics of the CSNP (Complete Sequence Number PDU)? (Select ALL that apply)",options:["A. Sent periodically by the DIS on broadcast networks","B. Contains a complete list of all LSPs in the sender's LSDB","C. Used by routers to identify which LSPs they are missing","D. Sent on P2P links every 10 seconds","E. Acknowledged by PSNP"],answerKey:["A","B","C","E"],explanation:"A — DIS sends CSNP every 10 seconds on broadcast networks ✓. B — CSNP lists ALL LSPs in the sender's LSDB (LSP ID + sequence number + checksum) ✓. C — Receiving routers compare CSNP with local LSDB to find missing or outdated LSPs ✓. D — WRONG: On P2P links, CSNP is only sent during INITIAL database synchronization (not periodically every 10 seconds like on broadcast). E — Routers send PSNP to acknowledge specific LSPs listed in CSNP or to request missing LSPs ✓."},
  {id:30,type:"multiple",topic:"Network Security",question:"Which of the following are correct descriptions of secure network management practices? (Select ALL that apply)",options:["A. Replace Telnet with SSH for remote device management","B. Use SNMPv3 with authPriv mode instead of SNMPv1/v2c","C. Disable unused management interfaces and ports","D. Use HTTPS instead of HTTP for web-based management","E. Configure RBAC (Role-Based Access Control) for different admin levels"],answerKey:["A","B","C","D","E"],explanation:"All five are correct security practices: A — SSH encrypts all terminal sessions ✓. B — SNMPv3 authPriv provides authentication + encryption vs SNMPv1/v2c plaintext ✓. C — Reducing attack surface by disabling unused services/ports ✓. D — HTTPS uses TLS encryption for web management ✓. E — RBAC limits what each admin can do based on role (principle of least privilege) ✓. These form the baseline of network device hardening following CIS Benchmarks and vendor security guidelines."},
  {id:31,type:"multiple",topic:"OSPF",question:"In an OSPF network with NSSA areas, which of the following are CORRECT? (Select ALL that apply)",options:["A. Type-7 LSAs are generated by ASBRs inside the NSSA area","B. The ABR converts Type-7 LSAs to Type-5 LSAs when advertising to other areas","C. NSSA areas still receive Type-5 LSAs from other areas","D. The P-bit in a Type-7 LSA controls whether the ABR translates it to Type-5","E. A default Type-3 route is injected into the NSSA by the ABR"],answerKey:["A","B","D","E"],explanation:"A — ASBRs inside NSSA generate Type-7 LSAs ✓. B — ABR translates Type-7 → Type-5 for other areas ✓. C — WRONG: NSSA areas BLOCK Type-5 LSAs from entering (that's the point of NSSA — preventing external LSAs from flooding in, similar to stub). D — P-bit (Propagate bit) = 1 means ABR should translate Type-7 to Type-5; P=0 means don't translate ✓. E — ABR injects a default Type-3 LSA into NSSA so routers can reach external destinations ✓."},
  {id:32,type:"multiple",topic:"VRRP",question:"Which of the following are CORRECT about VRRP Master/Backup behavior during normal operation? (Select ALL that apply)",options:["A. Only the Master responds to ARP requests for the virtual IP","B. The Master sends VRRP advertisement packets every 1 second by default","C. Both Master and Backup forward traffic to virtual IP destinations","D. The virtual MAC format is 00-00-5E-00-01-XX (XX = VRID in hex)","E. When a new Master takes over, it sends gratuitous ARP to update downstream ARP caches"],answerKey:["A","B","D","E"],explanation:"A — Only Master responds to ARP for virtual IP ✓. B — Default advertisement interval = 1 second ✓. C — WRONG: ONLY the Master forwards traffic. The Backup is in standby and does NOT forward traffic to the virtual IP. D — Virtual MAC = 00-00-5E-00-01-XX ✓. E — Gratuitous ARP after takeover forces downstream devices to update their ARP tables with the same virtual MAC, preventing traffic interruption ✓."},
  // ── ORDERING ──
  {id:33,type:"ordering",topic:"OSPF",question:"Arrange the following OSPF Virtual Link configuration steps in the correct order:",items:[{id:"a",text:"Verify the disconnected area now has logical connectivity to Area 0"},{id:"b",text:"Identify a non-backbone area to use as transit (must be standard, not stub/NSSA)"},{id:"c",text:"On both ABRs sharing the transit area, configure: area X vlink-peer <Router-ID>"},{id:"d",text:"Determine that a non-backbone area lacks direct connectivity to Area 0"},{id:"e",text:"Ensure both ABRs can reach each other's Router-IDs via OSPF within the transit area"}],correctOrder:["d","b","e","c","a"],explanation:"OSPF Virtual Link setup: 1) Identify the problem — non-backbone area not connected to Area 0. 2) Choose the transit area (standard area only; stub/NSSA cannot be transit). 3) Ensure the two ABRs are reachable within the transit area (OSPF must already be running between them there). 4) Configure virtual link on both ABRs using 'area X vlink-peer Router-ID'. 5) Verify adjacency forms across virtual link and the disconnected area exchanges routing with Area 0."},
  {id:34,type:"ordering",topic:"Multicast",question:"Arrange the PIM-DM flood-and-prune cycle in correct order:",items:[{id:"a",text:"Source starts sending multicast traffic"},{id:"b",text:"Routers with no downstream receivers send Prune messages upstream"},{id:"c",text:"Traffic is initially flooded to ALL downstream interfaces (diffusion)"},{id:"d",text:"Pruned branches stop receiving traffic for the Prune timeout period"},{id:"e",text:"State Refresh messages prevent prune state from expiring, avoiding re-flood"}],correctOrder:["a","c","b","d","e"],explanation:"PIM-DM flood-and-prune cycle: 1) Source sends first multicast packet. 2) PIM-DM immediately FLOODS traffic to all downstream PIM interfaces (diffusion/push model). 3) Routers with no downstream receivers send PRUNE messages upstream to stop traffic. 4) Upstream routers install prune state and stop forwarding on pruned branches. 5) State Refresh messages (sent by PIM-DM routers periodically) refresh prune state, preventing the 3-minute prune timeout expiry which would trigger another flood cycle."},
  {id:35,type:"ordering",topic:"BGP",question:"Arrange the following BGP confederations concepts in order from most fundamental to most operational:",items:[{id:"a",text:"External peers see only the confederation ID (original AS) in AS_PATH"},{id:"b",text:"Assign private sub-AS numbers to each confederation member group"},{id:"c",text:"Define the confederation identifier (the public AS number)"},{id:"d",text:"Run eBGP-like sessions between sub-ASes (CONFED_EBGP)"},{id:"e",text:"Run iBGP (full mesh or RR) within each sub-AS"}],correctOrder:["c","b","e","d","a"],explanation:"BGP Confederation logical build order: 1) Define confederation ID (the AS number the outside world sees). 2) Assign private sub-AS numbers to each group of routers (e.g., 65001, 65002). 3) Configure iBGP (full mesh or route reflectors) WITHIN each sub-AS. 4) Configure CONFED_EBGP sessions BETWEEN sub-ASes using the private sub-AS numbers. 5) Strip sub-AS numbers from AS_PATH when advertising to external EBGP peers — external world sees only the confederation ID."},
  // ── MORE TRUE/FALSE ──
  {id:36,type:"truefalse",topic:"Routing Policy",question:"Both MQC and PBR can be invoked on the device interface to filter the traffic of received and sent packets OR to control the forwarding path of packets.",answerKey:"False",explanation:"FALSE. MQC (Modular QoS Command) and PBR (Policy-Based Routing) have different capabilities: MQC — can filter/classify traffic and apply QoS actions (queuing, policing, shaping). It is primarily for traffic classification and QoS. PBR — controls the forwarding PATH of packets (overrides routing table). Key difference: PBR can control the forwarding PATH; MQC primarily handles QoS ACTIONS not path control. They cannot both be invoked on the same interface to control the forwarding path — PBR is specifically for path control, not MQC."},
  {id:37,type:"truefalse",topic:"OSPF",question:"In OSPF, a router can use 'import-route' to introduce routes from other OSPF processes into the current OSPF process.",answerKey:"True",explanation:"TRUE. On Huawei routers, if multiple OSPF processes run on the same router, routes from one OSPF process can be redistributed into another using 'import-route ospf N' (where N is the source process number). Each OSPF process is independent and has its own LSDB and routing table. Redistributing between OSPF processes is similar to redistributing between different routing protocols — it generates Type-5 External LSAs in the receiving process. This is useful for gradual network migrations or multi-domain OSPF scenarios."},
  {id:38,type:"truefalse",topic:"OSPF",question:"In an OSPF network, if two non-directly-connected routers with the same Router-ID run in the same region, it will cause problems with Type-1 (Router LSA) calculations.",answerKey:"True",explanation:"TRUE. OSPF Router-IDs must be unique throughout the OSPF domain. If two routers in the same area share a Router-ID: Both generate Type-1 Router-LSAs with the same Router-ID (same Advertising Router field). Receiving routers cannot distinguish between the two LSAs. One LSA will overwrite the other in the LSDB. SPF calculations will be based on incomplete/incorrect topology. This causes routing instability, incorrect path computation, and potentially routing loops or traffic blackholes. Non-directly-connected means the problem is less immediately obvious but still causes LSDB corruption."},
  {id:39,type:"truefalse",topic:"BGP",question:"When a device is attacked or misconfigured and BGP receives a large number of routes from its neighbors consuming device resources, BGP provides peer-based route control to limit the number of routes sent by neighbors, which can avoid such problems.",answerKey:"True",explanation:"TRUE. BGP route limit feature ('peer X.X.X.X route-limit N') on Huawei routers: Limits the maximum number of routes received from a specific peer. When the limit is reached, either: Alert mode — log a warning but continue accepting. Alert-only mode — accept up to limit, then only alert (no disconnect). Idle-forever mode — terminate the session when limit exceeded. This protects against: BGP route leak attacks, misconfigured peers advertising too many routes, route table overflow. Essential for IXP peering and large-scale BGP deployments."},
  {id:40,type:"truefalse",topic:"OSPF",question:"In the OSPF neighbor state, the 2-Way state means that both routers have confirmed that they can receive each other's Hello packets, i.e., bidirectional communication has been established.",answerKey:"True",explanation:"TRUE. OSPF 2-Way state: A router receives a Hello packet from a neighbor AND sees its own Router-ID listed in that neighbor's Hello packet (in the Neighbor field). This confirms BIDIRECTIONAL communication — both routers can send and receive from each other. At 2-Way state: DR/BDR election occurs (on broadcast/NBMA networks). Routers decide whether to form Full adjacency (with DR/BDR) or stay at 2-Way (DROther to DROther on broadcast networks). 2-Way is the final state for non-adjacent pairs; Full adjacency requires proceeding to ExStart/Exchange/Loading/Full."},
  {id:41,type:"truefalse",topic:"STP",question:"When the IGMP snooping version on a device is LOWER than that of the user host, the user cannot receive multicast data because the device forwards the IGMP Report to the router port and does not generate member ports or forwarding entries.",answerKey:"True",explanation:"TRUE. Version mismatch problem: If switch runs IGMPv2 snooping but host sends IGMPv3 reports, the switch cannot parse the IGMPv3-specific format (source-specific joins). The switch treats the unknown message format as unrecognized and floods it to router ports but doesn't create proper member port entries. Without member port entries, multicast traffic is not forwarded to the host's port. Result: host sends join but receives no multicast. Solution: configure the same or higher IGMP snooping version on the switch as the hosts use."},
  {id:42,type:"truefalse",topic:"OSPF",question:"In an OSPF network, the ABR of the NSSA area will NOT flood the NSSA with Category-4 and Category-5 LSAs, but WILL convert the Category-7 LSA to the Category-5 LSA to flood to other areas.",answerKey:"True",explanation:"TRUE. NSSA ABR behavior: Inbound (from other areas INTO NSSA): Type-4 and Type-5 LSAs are BLOCKED from entering the NSSA area — the ABR does not flood them into the NSSA. Outbound (from NSSA TO other areas): Type-7 LSAs generated by the ASBR inside the NSSA are CONVERTED by the ABR to Type-5 LSAs before being flooded to other areas. This allows the NSSA to have an ASBR (unlike stub areas) while still reducing LSA load from the rest of the OSPF domain."},
  {id:43,type:"truefalse",topic:"BGP",question:"In BGP, the MED attribute is passed only between adjacent ASes. The AS that receives it does not advertise it to any third-party AS. By default, the router only compares the MED values of BGP routes from the same neighboring AS.",answerKey:"True",explanation:"TRUE. MED propagation rules: MED is passed from AS1 to AS2 via EBGP (adjacent ASes). When AS2 advertises the route to AS3, the MED is NOT included (stripped by default) — non-transitive. Within AS2 (IBGP): MED is preserved. Comparison rule: By default, MED is only compared between routes from the SAME neighboring AS. Routes from AS1 with MED=100 and routes from AS3 with MED=200 to the same destination are NOT compared by default. To compare across different neighbor ASes, use 'bestroute med-confederation' or 'compare-different-as-med'."},
  {id:44,type:"truefalse",topic:"BGP",question:"In a BGP route reflection scenario, when RR reflects a route from a client, it adds the CLUSTER_ID to the CLUSTER_LIST. If a router receives this route and finds its own Cluster-ID in the CLUSTER_LIST, it discards the route to prevent loops.",answerKey:"True",explanation:"TRUE. This is the CLUSTER_LIST loop prevention mechanism: RR appends its Cluster-ID when reflecting routes. A router checks incoming routes' CLUSTER_LIST. If own Cluster-ID is present → LOOP DETECTED → discard route. This prevents: Route from going around in circles between RRs in different clusters. Routing loops in multi-cluster RR topologies. Works together with ORIGINATOR_ID (prevents a client from accepting its own route reflected back)."},
  // ── FINAL SINGLE CHOICE ──
  {id:45,type:"single",topic:"OSPF",question:"In a broadcast OSPF network, which packets use UNICAST transmission by default (not multicast)?",options:["A. Hello packets","B. LSU (Link State Update) and LSAck packets when sent to specific neighbors","C. DD (Database Description) and LSR (Link State Request) packets","D. All OSPF packets on broadcast networks use multicast"],answerKey:"C",explanation:"OSPF packet transmission on Broadcast networks: Hello → multicast 224.0.0.5 ✓ (periodic discovery). DD (DBD) → UNICAST to specific neighbor (used during ExStart/Exchange for reliable DB sync). LSR → UNICAST to specific neighbor (requesting specific LSAs). LSU → can be unicast or multicast (224.0.0.5 for DR/BDR to DROthers, or unicast as acknowledgment). LSAck → can be unicast or delayed multicast. The DD and LSR are always unicast because they're part of a specific neighbor exchange that requires reliable delivery to a single peer."},
  {id:46,type:"single",topic:"BGP",question:"When BGP confederation is used to solve iBGP scalability, what happens to the confederation sub-AS numbers in the AS_PATH when the route is advertised to an external (non-confederation) EBGP peer?",options:["A. Sub-AS numbers are kept in the AS_PATH as CONFED_SEQUENCE","B. Sub-AS numbers are stripped from the AS_PATH; only the confederation identifier appears","C. The entire AS_PATH is replaced with just the confederation ID","D. Sub-AS numbers are converted to regular AS numbers in AS_PATH"],answerKey:"B",explanation:"BGP confederation AS_PATH handling: WITHIN confederation: AS_PATH uses CONFED_SEQUENCE and CONFED_SET to track sub-AS hops (visible internally). TO EXTERNAL PEERS: The confederation sub-AS numbers (private) are completely STRIPPED from the AS_PATH. Only the public confederation identifier (the original AS number) appears in the AS_PATH. External peers see the confederation as a single AS — they have no visibility into the internal sub-AS structure. This maintains backward compatibility and privacy of internal structure."},
  {id:47,type:"single",topic:"Routing",question:"On Huawei VRP, what is the default route preference value for OSPF routes?",options:["A. 15","B. 60","C. 10","D. 100"],answerKey:"C",explanation:"Huawei VRP default route preferences (lower = more preferred): Direct = 0 (most preferred). Static = 60. OSPF Internal = 10 ✓. OSPF External = 150. IS-IS = 15. RIP = 100. iBGP = 255. eBGP = 255. Note: OSPF Internal (intra-area and inter-area) routes have preference 10. OSPF External (Type 1 and Type 2) routes have preference 150. These differ from Cisco's Administrative Distance values (OSPF = 110 in Cisco)."},
  {id:48,type:"single",topic:"WLAN",question:"In WLAN, which authentication method requires NO client software installation and uses the terminal's hardware identifier for access control?",options:["A. 802.1X authentication","B. Portal (web) authentication","C. MAC address authentication","D. WPA3-Enterprise authentication"],answerKey:"C",explanation:"MAC address authentication characteristics: No client software required — the switch/AP reads the MAC address automatically at connection. Uses the terminal's MAC address as username and (usually) a derived value as password. Sent to RADIUS server for verification against an allowlist. Advantages: Zero client-side configuration, works with any device (IoT, printers, etc.). Disadvantages: MAC addresses can be spoofed, no user-based identification. Contrast: 802.1X requires supplicant software. Portal requires a web browser login page. MAC auth is truly zero-touch from the client perspective."},
  {id:49,type:"single",topic:"BGP",question:"In BGP, when a route is learned from multiple EBGP peers vs a single IBGP peer, what determines whether EBGP or IBGP route is preferred (assuming all other attributes are equal)?",options:["A. IBGP routes are always preferred over EBGP routes","B. EBGP routes are preferred over IBGP routes in BGP path selection","C. The router selects based on IGP metric to the next-hop only","D. EBGP and IBGP routes are treated equally"],answerKey:"B",explanation:"In BGP path selection (after checking Preferred-value, LOCAL_PREF, AS_PATH, ORIGIN, MED), the next tiebreaker is: EBGP routes are preferred over IBGP routes. This makes intuitive sense: EBGP routes come directly from external peers (more authoritative), while IBGP routes are reflections within the AS. After EBGP/IBGP comparison: IGP metric to next-hop is compared (lower is better). Then: Oldest EBGP route (for stability). Finally: Router-ID and peer IP address as final tiebreakers."},
  {id:50,type:"single",topic:"IS-IS",question:"In IS-IS, what is the maximum number of NETs (Network Entity Titles) that can be configured on a single Huawei router?",options:["A. 1","B. 3","C. 5","D. 10"],answerKey:"B",explanation:"A Huawei IS-IS router can be configured with up to 3 NETs simultaneously. This is used during area merging or splitting — you can configure the new area address while the old one is still active, allowing gradual migration without service interruption. All configured NETs must have the SAME System-ID (6 bytes) — only the Area Address portion can differ. After migration completes, remove the old NET. This is an IS-IS operational advantage over OSPF where area re-addressing is more complex."},
  {id:51,type:"single",topic:"OSPF",question:"Which of the following descriptions about OSPF Type-2 external route cost calculation is CORRECT?",options:["A. E2 cost = external metric + internal OSPF cost to ASBR","B. E2 cost = external metric ONLY (internal cost to ASBR is ignored)","C. E2 cost = internal OSPF cost only (external metric is ignored)","D. E2 and E1 use the same cost calculation"],answerKey:"B",explanation:"OSPF external route cost types: E1 (Type 1) — Total cost = External metric + Internal OSPF cost to reach the ASBR. E2 (Type 2, DEFAULT) — Total cost = External metric ONLY (ignores internal OSPF cost to reach ASBR). Preference: E1 over E2 (when comparing to same destination, E1 accounts for full path cost). E2 simplicity: The external metric remains constant regardless of how far the ASBR is. When comparing two E2 routes with same metric, IGP cost to ASBR is then used as tiebreaker."},
  {id:52,type:"single",topic:"Firewall",question:"In Huawei USG firewall, what is the priority of the DMZ (Demilitarized Zone) security zone?",options:["A. 100","B. 85","C. 50","D. 5"],answerKey:"C",explanation:"Huawei USG default security zone priorities: Local = 100 (the firewall itself — highest trust). Trust = 85 (internal LAN). DMZ = 50 (servers accessible from internet — medium trust). Untrust = 5 (internet/external — lowest trust). Traffic direction: High→Low priority = outbound (typically less restricted). Low→High priority = inbound (typically restricted, requires explicit policy). The DMZ at 50 sits between Trust (85) and Untrust (5), reflecting its semi-trusted nature — accessible from internet but more controlled than the internal LAN."},
  {id:53,type:"single",topic:"OSPF",question:"In an OSPF network, which of the following descriptions about Type-3 (Network Summary) LSAs is CORRECT?",options:["A. Type-3 LSAs are generated by ASBRs","B. Type-3 LSAs describe routes learned from outside the OSPF AS","C. Type-3 LSAs are generated by ABRs and describe inter-area routes","D. Type-3 LSAs are flooded throughout the entire OSPF domain without change"],answerKey:"C",explanation:"Type-3 (Network Summary LSA) facts: Generated by ABRs (not ASBRs) ✓. Describe inter-area routes — routes from one area to be advertised into another area. ABRs create new Type-3 LSAs for each inter-area route (they don't simply forward; they regenerate the LSA). Flooded within individual areas (NOT unchanged across the entire domain — each ABR creates new Type-3 LSAs for its areas). Type-5 LSAs describe external routes (from ASBRs). Type-3 describes inter-area routes from ABRs — option C is correct."},
  {id:54,type:"single",topic:"BGP",question:"Which of the following accurately describes the function of the 'peer next-hop-local' command in BGP?",options:["A. Sets the next-hop to the peer's IP address","B. Forces the router to set itself (its own interface IP) as the next-hop when advertising routes to IBGP peers","C. Prevents next-hop changes for EBGP routes","D. Sets the next-hop to the loopback interface IP"],answerKey:"B",explanation:"'peer next-hop-local' command: When advertising routes to an IBGP peer, the router sets its own IP address as the NEXT_HOP attribute instead of keeping the original next-hop. Without this: IBGP routes may carry an EBGP peer's IP as next-hop, which IBGP peers may not be able to reach (causing route black holes). With 'peer next-hop-local': The IBGP peer can always reach the next-hop (it points to the advertising router, which is directly reachable). Commonly used on PE routers or route reflectors where the original EBGP next-hop is unreachable by IBGP peers."},
  {id:55,type:"single",topic:"OSPF",question:"In OSPF, what is the purpose of the DD (Database Description) sequence number during the ExStart and Exchange states?",options:["A. To identify different OSPF processes on the same router","B. To provide reliable, ordered delivery of DD packets between neighbors","C. To set the priority for DR election","D. To identify the Router-ID of the sending router"],answerKey:"B",explanation:"DD sequence numbers provide reliable delivery: During ExStart: Both routers propose initial DD sequence numbers; the Master's sequence number is used. During Exchange: Each DD packet has a sequence number. The receiver acknowledges by sending the next expected DD with the same or incremented sequence number. If no acknowledgment within the retransmit timer, the DD is resent. This ensures: All LSA header information in DD packets is received in order. No DD packets are lost. The database description is complete before moving to Loading state. It's essentially a simple reliable transport within OSPF."},
  {id:56,type:"single",topic:"BGP",question:"In a network using OSPF as the IGP and BGP for inter-AS routing, what is the relationship between OSPF routes and BGP routes in the routing table?",options:["A. BGP routes always override OSPF routes to the same destination","B. OSPF routes (preference 10) are preferred over BGP routes (preference 255) for the same prefix","C. They cannot coexist — one must be disabled","D. BGP internal routes have lower preference number than OSPF external routes"],answerKey:"B",explanation:"Route preference comparison on Huawei VRP: OSPF Internal = preference 10. OSPF External = preference 150. BGP (iBGP and eBGP) = preference 255. LOWER preference = MORE preferred. For the same prefix, OSPF routes (preference 10) are far more preferred than BGP routes (preference 255). In practice, BGP and OSPF route tables are separate domains — OSPF carries IGP prefixes, BGP carries internet prefixes. They rarely compete for the same prefix, but when they do (e.g., during redistribution), OSPF wins by far."},
  {id:57,type:"single",topic:"Multicast",question:"In PIM-SM, what is the role of the DR (Designated Router) on a multi-access segment?",options:["A. Same role as OSPF DR — reduces adjacency overhead","B. On the source side: sends PIM Register to RP. On the receiver side: sends PIM Join toward RP","C. Elects the RP for the multicast group","D. Only forwards traffic on the shared tree"],answerKey:"B",explanation:"PIM DR on multi-access segments: Source-side DR: The PIM DR on the source's subnet is responsible for sending PIM Register messages to the RP when the source starts sending. It encapsulates multicast data in Register unicast packets to the RP. Receiver-side DR: The PIM DR on the receiver's subnet is responsible for sending PIM Join messages toward the RP when a host joins a group (via IGMP). It builds the shared tree from the receiver side. DR election: Highest DR priority wins; equal priority → highest IP address. This is different from OSPF DR — PIM DR is about controlling register/join responsibilities, not adjacency reduction."},
  {id:58,type:"single",topic:"BGP",question:"What is the ORIGINATOR_ID attribute in BGP route reflection, and what is its purpose?",options:["A. Identifies the AS where the route originated","B. Contains the Router-ID of the client that originally sent the route to the RR; prevents clients from accepting their own reflected routes","C. Identifies the Route Reflector that reflected the route","D. Contains the cluster ID to prevent inter-cluster loops"],answerKey:"B",explanation:"ORIGINATOR_ID in BGP route reflection: Added by the RR when it first reflects a client's route. Contains the BGP Router-ID of the originating client router. Loop prevention: When a router receives a route, it checks if ORIGINATOR_ID equals its own Router-ID. If YES — this is its own route being reflected back → DISCARD. This prevents a client from installing a reflected version of its own route. Note: CLUSTER_LIST prevents inter-cluster loops; ORIGINATOR_ID prevents intra-cluster client loops. The RR itself is identified by the Cluster-ID in CLUSTER_LIST."},
  {id:59,type:"single",topic:"Security",question:"Which encryption algorithm is asymmetric (uses a key pair of public and private keys)?",options:["A. AES-256","B. DES","C. RSA","D. 3DES"],answerKey:"C",explanation:"Asymmetric vs symmetric encryption: RSA (Rivest-Shamir-Adleman) — ASYMMETRIC: uses a mathematically linked key pair (public key for encryption/verification, private key for decryption/signing). Used for key exchange, digital signatures, and certificate-based authentication ✓. AES (Advanced Encryption Standard) — SYMMETRIC: same key for encrypt and decrypt. DES (Data Encryption Standard) — SYMMETRIC: same key. 3DES (Triple DES) — SYMMETRIC: applies DES three times with up to three different keys. Symmetric algorithms are faster and used for bulk data; asymmetric for key exchange and authentication."},
  {id:60,type:"single",topic:"OSPF",question:"In OSPF, which of the following correctly describes the relationship between OSPF cost and interface bandwidth using the default reference bandwidth?",options:["A. Higher bandwidth = lower cost (OSPF prefers higher-bandwidth paths)","B. Cost is fixed at 1 regardless of bandwidth","C. Cost = bandwidth / reference bandwidth (GE interface has cost 1)","D. Cost = reference bandwidth × interface bandwidth"],answerKey:"A",explanation:"OSPF interface cost formula: Cost = Reference_bandwidth / Interface_bandwidth (rounded up to minimum 1). Default reference bandwidth = 100 Mbps (100,000 kbps) on most implementations. 100 Mbps (FastEthernet) = 100/100 = cost 1. 10 Mbps = 100/10 = cost 10. 1000 Mbps (GigE) = 100/1000 = 0.1 → rounds up to cost 1 (same as FastEthernet!). This is why the reference bandwidth should be increased with 'bandwidth-reference N' on modern networks. Higher bandwidth = lower cost = preferred by OSPF SPF — option A is correct."},
];

const TC={OSPF:"#00d4ff","IS-IS":"#a78bfa",BGP:"#fbbf24",VRRP:"#34d399",BFD:"#06b6d4",Multicast:"#f472b6",Firewall:"#f87171",STP:"#8b5cf6",WLAN:"#fb923c",ACL:"#38bdf8",IPv6:"#60a5fa","Routing Policy":"#4ade80",VPN:"#fb7185",Security:"#f97316",Routing:"#a3e635",DHCPv6:"#fcd34d","Network Security":"#e879f9",PBR:"#a3e635","PIM-SM":"#f472b6","PIM-DM":"#f472b6"};

export default function HCIPBatch7(){
  const[cur,setCur]=useState(0);const[ans,setAns]=useState({});const[sub,setSub]=useState({});const[showExp,setShowExp]=useState({});const[drag,setDrag]=useState({});const[dOver,setDOver]=useState(null);const[view,setView]=useState("exam");const[time,setTime]=useState(0);const tRef=useRef(null);const dIdx=useRef(null);
  useEffect(()=>{tRef.current=setInterval(()=>setTime(t=>t+1),1000);return()=>clearInterval(tRef.current);},[]);
  const fmt=s=>`${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`;
  const q=QUESTIONS[cur];const tc=TC[q.topic]||"#00d4ff";const done=Object.keys(sub).length;
  useEffect(()=>{if(q.type==="ordering"&&!drag[q.id]){setDrag(p=>({...p,[q.id]:[...q.items].sort(()=>Math.random()-0.5).map(i=>i.id)}));};},[q.id]);
  const isOk=id=>{const qd=QUESTIONS.find(x=>x.id===id);if(!qd)return false;if(qd.type==="single")return ans[id]===qd.answerKey;if(qd.type==="truefalse")return ans[id]===qd.answerKey;if(qd.type==="multiple")return(ans[id]||[]).sort().join()===[...qd.answerKey].sort().join();if(qd.type==="ordering")return(drag[id]||qd.items.map(i=>i.id)).join()===qd.correctOrder.join();return false;};
  const submit=()=>{if(sub[q.id])return;if(q.type==="ordering"){setSub(p=>({...p,[q.id]:true}));setShowExp(p=>({...p,[q.id]:true}));return;}const a=ans[q.id];if(!a||(Array.isArray(a)&&!a.length))return;setSub(p=>({...p,[q.id]:true}));setShowExp(p=>({...p,[q.id]:true}));};
  const cls=(letter,qd)=>{if(!sub[qd.id]){const s=qd.type==="multiple"?(ans[qd.id]||[]).includes(letter):ans[qd.id]===letter;return s?"opt sel":"opt";}const c=qd.type==="multiple"?qd.answerKey.includes(letter):qd.answerKey===letter;const s=qd.type==="multiple"?(ans[qd.id]||[]).includes(letter):ans[qd.id]===letter;if(c)return"opt ok";if(s)return"opt bad";return"opt";};
  const oItems=(drag[q.id]||[]).map(id=>q.items?.find(i=>i.id===id)).filter(Boolean);
  if(view==="results"){let s=0;QUESTIONS.forEach(qq=>{if(sub[qq.id]&&isOk(qq.id))s++;});const pct=Math.round(s/QUESTIONS.length*100);const bd={};QUESTIONS.forEach(qq=>{if(!bd[qq.topic])bd[qq.topic]={t:0,c:0};bd[qq.topic].t++;if(sub[qq.id]&&isOk(qq.id))bd[qq.topic].c++;});
    return(<div style={S.wrap}><style>{css}</style><div style={S.rWrap}><div style={S.rHead}><div style={{fontSize:10,color:"#555",letterSpacing:3}}>🏁 FINAL BATCH COMPLETE · Q361–420</div><div style={{fontSize:66,fontFamily:"monospace",color:pct>=60?"#00d4ff":"#f87171",lineHeight:1.1,marginTop:8}}>{pct}%</div><div style={{color:"#555",fontSize:12,marginTop:6}}>{s}/{QUESTIONS.length} correct · {fmt(time)}</div><div style={{marginTop:10,fontSize:13,color:pct>=80?"#34d399":pct>=60?"#fbbf24":"#f87171"}}>{pct>=80?"🏆 Outstanding! You're exam-ready.":pct>=60?"✅ Passing — you're getting there!":"📚 Review and retry — you can do it!"}</div><div style={{marginTop:16,padding:"12px",background:"rgba(0,212,255,.05)",border:"1px solid #0e2233",borderRadius:6,fontSize:11,color:"#666",lineHeight:1.7}}>✅ All 7 batches complete!<br/>420 questions covering the full HCIP-Datacom H12-821 syllabus.<br/>Good luck on your exam! 🎯</div></div><div style={S.breakdown}><div style={{fontSize:10,color:"#333",letterSpacing:2,marginBottom:12}}>TOPIC BREAKDOWN</div>{Object.entries(bd).map(([topic,d])=>{const p=d.t?Math.round(d.c/d.t*100):0;const color=TC[topic]||"#00d4ff";return(<div key={topic} style={{marginBottom:9}}><div style={{display:"flex",justifyContent:"space-between",fontSize:11,marginBottom:3}}><span style={{color}}>{topic}</span><span style={{color:"#444"}}>{d.c}/{d.t}</span></div><div style={{background:"#0a0a0a",borderRadius:2,height:3}}><div style={{width:`${p}%`,height:"100%",background:color,borderRadius:2}}/></div></div>);})}</div><button style={{...S.btn,width:"100%",marginTop:18}} onClick={()=>{setAns({});setSub({});setShowExp({});setDrag({});setTime(0);setCur(0);setView("exam");tRef.current=setInterval(()=>setTime(t=>t+1),1000);}}>RETRY BATCH 7</button></div></div>);}
  return(<div style={S.wrap}><style>{css}</style><div style={S.hdr}><div style={{fontSize:10,color:"#00d4ff",letterSpacing:3}}>HCIP-DATACOM · BATCH 7 (FINAL)</div><div style={{fontFamily:"monospace",fontSize:12,color:"#444"}}>{fmt(time)}</div></div><div style={{display:"flex",justifyContent:"space-between",padding:"5px 16px",fontSize:10,color:"#444"}}><span>Q{cur+1}/{QUESTIONS.length}</span><span>{done} answered</span></div><div style={{height:2,background:"#0a0a0f",margin:"0 16px",borderRadius:2,position:"relative",overflow:"hidden"}}><div style={{position:"absolute",height:"100%",background:"#181828",width:`${(cur+1)/QUESTIONS.length*100}%`}}/><div style={{position:"absolute",height:"100%",background:"#00d4ff",width:`${done/QUESTIONS.length*100}%`}}/></div><div style={{display:"flex",flexWrap:"wrap",gap:3,padding:"7px 16px"}}>{QUESTIONS.map((qq,i)=>(<div key={qq.id} onClick={()=>setCur(i)} style={{width:7,height:7,borderRadius:"50%",cursor:"pointer",background:i===cur?"#00d4ff":sub[qq.id]?(isOk(qq.id)?"#34d399":"#f87171"):"#111"}}/>))}</div>
  <div style={S.card}><div style={{fontSize:10,color:"#444",letterSpacing:1.5,marginBottom:12}}><span style={{color:tc}}>◆</span> {q.topic}<span style={{marginLeft:10}}>{q.type==="single"&&"Single Choice"}{q.type==="truefalse"&&"True / False"}{q.type==="multiple"&&"Multiple Choice"}{q.type==="ordering"&&"Drag to Order"}</span></div><div style={S.qText}>{q.question}</div>
  {q.type==="single"&&(<div style={{display:"flex",flexDirection:"column",gap:6,marginTop:14}}>{q.options.map(opt=>{const l=opt.split(".")[0].trim();return(<button key={l} className={cls(l,q)} onClick={()=>!sub[q.id]&&setAns(p=>({...p,[q.id]:l}))} style={S.optB}><span style={{minWidth:16,color:"#333",fontWeight:700}}>{l}</span><span>{opt.slice(opt.indexOf(".")+1).trim()}</span></button>);})}</div>)}
  {q.type==="truefalse"&&(<div style={{display:"flex",gap:10,marginTop:16}}>{["True","False"].map(v=>{let c="opt";if(sub[q.id]){if(v===q.answerKey)c="opt ok";else if(ans[q.id]===v)c="opt bad";}else if(ans[q.id]===v)c="opt sel";return(<button key={v} className={c} onClick={()=>!sub[q.id]&&setAns(p=>({...p,[q.id]:v}))} style={{...S.optB,flex:1,justifyContent:"center",fontSize:13,fontWeight:700}}>{v==="True"?"✓  True":"✗  False"}</button>);})}</div>)}
  {q.type==="multiple"&&(<div style={{display:"flex",flexDirection:"column",gap:6,marginTop:14}}>{q.options.map(opt=>{const l=opt.split(".")[0].trim();return(<button key={l} className={cls(l,q)} onClick={()=>{if(sub[q.id])return;const c=ans[q.id]||[];setAns(p=>({...p,[q.id]:c.includes(l)?c.filter(x=>x!==l):[...c,l]}));}} style={S.optB}><span style={{minWidth:16,color:"#333",fontWeight:700}}>{l}</span><span>{opt.slice(opt.indexOf(".")+1).trim()}</span></button>);})}</div>)}
  {q.type==="ordering"&&(<><div style={{fontSize:10,color:"#fbbf24",marginTop:10,marginBottom:7}}>▸ Drag into correct order — top = first</div>{oItems.map((item,idx)=>{const good=sub[q.id]&&q.correctOrder[idx]===item.id;const bad=sub[q.id]&&q.correctOrder[idx]!==item.id;return(<div key={item.id} draggable={!sub[q.id]} onDragStart={()=>{dIdx.current=idx;}} onDragEnter={()=>setDOver(idx)} onDragOver={e=>e.preventDefault()} onDragEnd={()=>{if(dIdx.current!==null&&dOver!==null){const o=[...(drag[q.id]||[])];const[m]=o.splice(dIdx.current,1);o.splice(dOver,0,m);setDrag(p=>({...p,[q.id]:o}));}dIdx.current=null;setDOver(null);}} style={{display:"flex",alignItems:"center",padding:"8px 11px",marginBottom:4,borderRadius:5,border:`1px solid ${good?"#34d399":bad?"#f87171":dOver===idx?"#00d4ff":"#1a1a28"}`,background:good?"rgba(52,211,153,.1)":bad?"rgba(248,113,113,.08)":dOver===idx?"rgba(0,212,255,.06)":"#0c0c18",cursor:sub[q.id]?"default":"grab"}}><span style={{color:"#2a2a3a",fontSize:10,minWidth:16}}>{idx+1}.</span>{!sub[q.id]&&<span style={{color:"#222",marginRight:6,fontSize:10}}>⠿</span>}{good&&<span style={{color:"#34d399",marginRight:5}}>✓</span>}{bad&&<span style={{color:"#f87171",marginRight:5}}>✗</span>}<span style={{fontSize:12,color:"#bbb"}}>{item.text}</span></div>);})}
  {sub[q.id]&&<div style={{marginTop:9,fontSize:10,color:"#444"}}><span style={{color:"#00d4ff"}}>Correct: </span>{q.correctOrder.map((id,i)=>{const item=q.items.find(x=>x.id===id);return<span key={id} style={{color:"#888"}}>{i+1}. {item?.text}{i<q.correctOrder.length-1?" → ":""}</span>;})}</div>}</>)}
  {!sub[q.id]&&<button style={S.sub} onClick={submit}>Submit Answer</button>}
  {sub[q.id]&&(<div style={{...S.res,background:isOk(q.id)?"rgba(52,211,153,.08)":"rgba(248,113,113,.08)",borderColor:isOk(q.id)?"#34d399":"#f87171",color:isOk(q.id)?"#34d399":"#f87171"}}>{isOk(q.id)?"✓ CORRECT":"✗ INCORRECT"}{!isOk(q.id)&&q.type!=="ordering"&&<span style={{color:"#444",fontWeight:400,fontSize:11}}> · Answer: <span style={{color:"#34d399"}}>{Array.isArray(q.answerKey)?q.answerKey.join(", "):q.answerKey}</span></span>}</div>)}
  {showExp[q.id]&&(<div style={S.expBox}><div style={{fontSize:10,color:"#00d4ff",letterSpacing:2,marginBottom:6}}>EXPLANATION</div><div style={{fontSize:12,color:"#888",lineHeight:1.8}}>{q.explanation}</div></div>)}
  </div>
  <div style={S.nav}><button style={{...S.navB,opacity:cur===0?0.3:1}} disabled={cur===0} onClick={()=>setCur(c=>Math.max(0,c-1))}>← PREV</button><span style={{fontSize:10,color:"#333"}}>{cur+1} / {QUESTIONS.length}</span>{cur<QUESTIONS.length-1?<button style={S.navB} onClick={()=>setCur(c=>c+1)}>NEXT →</button>:<button style={{...S.navB,background:"#34d399",color:"#000",fontWeight:700}} onClick={()=>{clearInterval(tRef.current);setView("results");}}>🏁 FINISH</button>}</div>
  <div style={{textAlign:"center",fontSize:10,color:"#1a1a1a",paddingBottom:14}}>HCIP-Datacom H12-821 · 🏁 FINAL BATCH 7 of 7 · {done} answered · {QUESTIONS.length-done} remaining</div></div>);
}
const S={wrap:{minHeight:"100vh",background:"#07070d",fontFamily:"'JetBrains Mono','Fira Code','Courier New',monospace",color:"#ddd",paddingBottom:40},hdr:{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"12px 16px 10px",borderBottom:"1px solid #0e0e18"},card:{margin:"5px 13px",background:"#0b0b17",border:"1px solid #161626",borderRadius:7,padding:"16px"},qText:{fontSize:13,lineHeight:1.85,color:"#d0d0d0"},optB:{display:"flex",alignItems:"flex-start",gap:9,padding:"9px 12px",borderRadius:5,border:"1px solid #1a1a28",background:"#070710",color:"#bbb",fontSize:12,textAlign:"left",cursor:"pointer",width:"100%",lineHeight:1.5,fontFamily:"inherit"},sub:{marginTop:16,width:"100%",padding:"10px",background:"#00d4ff",color:"#000",border:"none",borderRadius:5,fontSize:11,fontWeight:700,letterSpacing:2,cursor:"pointer",fontFamily:"inherit"},res:{marginTop:12,padding:"8px 12px",borderRadius:5,border:"1px solid",fontSize:12,fontWeight:700,letterSpacing:1},expBox:{marginTop:12,padding:"12px",background:"#07070e",border:"1px solid #111120",borderRadius:5},nav:{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"12px 16px"},navB:{padding:"6px 14px",background:"#0e0e1c",color:"#00d4ff",border:"1px solid #1a1a2a",borderRadius:4,fontSize:10,letterSpacing:1.5,cursor:"pointer",fontFamily:"inherit",fontWeight:700},btn:{padding:"10px",background:"#00d4ff",color:"#000",border:"none",borderRadius:5,fontSize:11,fontWeight:700,letterSpacing:2,cursor:"pointer",fontFamily:"inherit"},rWrap:{maxWidth:460,margin:"0 auto",padding:"32px 16px"},rHead:{textAlign:"center",padding:"26px 16px",background:"#0b0b17",border:"1px solid #161626",borderRadius:7,marginBottom:16},breakdown:{background:"#0b0b17",border:"1px solid #161626",borderRadius:7,padding:"16px"},};
const css=`@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;700&display=swap');*{box-sizing:border-box;}.opt{display:flex;align-items:flex-start;gap:9px;padding:9px 12px;border-radius:5px;border:1px solid #1a1a28;background:#070710;color:#bbb;font-size:12px;text-align:left;cursor:pointer;width:100%;line-height:1.5;font-family:inherit;transition:all .1s;}.opt:hover:not(.ok):not(.bad){border-color:#242438;background:#0d0d20;}.opt.sel{border-color:#00d4ff;background:rgba(0,212,255,.06);color:#e0e0e0;}.opt.ok{border-color:#34d399;background:rgba(52,211,153,.09);color:#6ee7b7;cursor:default;}.opt.bad{border-color:#f87171;background:rgba(248,113,113,.07);color:#fca5a5;cursor:default;}`;

